import random
random.seed(6)
def parse(s):
    if not s.startswith("JAH-"): raise ValueError("bad prefix")
    return s[4:]
crashes = 0
alphabet = "JAH-0123456789xyz!"
for _ in range(300):
    s = "".join(random.choice(alphabet) for _ in range(random.randint(0, 8)))
    try: parse(s)
    except ValueError: crashes += 1
print("inputs rejected cleanly:", crashes, "/300 (no hangs, no escapes)")
assert crashes > 200

import random
random.seed(11)
corpus = ["JAH-1"]
def mutate(s):
    s = list(s)
    s[random.randrange(len(s))] = random.choice("JAH-019")
    return "".join(s)
seen = set()
for _ in range(50):
    m = mutate(random.choice(corpus))
    if m not in seen: seen.add(m); corpus.append(m)
print("corpus grew to:", len(corpus))
assert len(corpus) > 10

arcs = set()
def classify(x):
    r = "neg" if x < 0 else ("zero" if x == 0 else "pos")
    arcs.add(x < 0); arcs.add(x == 0)
    return r
for v in [-1, 0, 5]: classify(v)
print("branch outcomes seen:", arcs)
assert arcs == {True, False}
